import networkx as nx
import pulp

def rdn(G):
    prob = pulp.LpProblem('RDN', pulp.LpMinimize)
    nodes = list(G.nodes())
    x = {v: pulp.LpVariable(f'x_{v}', cat='Binary') for v in nodes}
    y = {v: pulp.LpVariable(f'y_{v}', cat='Binary') for v in nodes}
    prob += pulp.lpSum([x[v] + 2*y[v] for v in nodes])
    for v in nodes:
        prob += x[v] + y[v] <= 1
        # v dominated: either x[v]==1, y[v]==1, or neighbor has y[u]==1
        prob += x[v] + y[v] + pulp.lpSum([y[u] for u in G.neighbors(v)]) >= 1
    prob.solve(pulp.PULP_CBC_CMD(msg=0))
    return int(round(pulp.value(prob.objective)))

